<?php
declare(strict_types=1);
namespace App\Interface\Http\Catalog;
use App\Application\Catalog\DTO\Request\CreateSubjectRequestDto;use App\Application\Catalog\Mapper\SubjectResponseMapper;use App\Application\Catalog\Service\CreateSubjectService;use App\Application\Catalog\Service\ListSubjectsService;use App\Application\Identity\DTO\Response\CurrentUserResponseDto;use App\Application\Identity\Service\AuthService;use App\Domain\Identity\Exception\UnavailableUserException;use App\Infrastructure\Http\ApiResponseFactory;use App\Infrastructure\Persistence\Doctrine\Catalog\DoctrineSubjectRepository;use App\Infrastructure\Persistence\Doctrine\DoctrineEntityManagerFactory;use App\Infrastructure\Persistence\Doctrine\DoctrineTransactionManager;use App\Interface\Http\Identity\IdentityRequestFactory;use DomainException;use InvalidArgumentException;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;use Slim\App;
final class SubjectRouteRegistrar {public function __construct(private readonly ApiResponseFactory $responses,private readonly AuthService $auth){}public function register(App $app):void{$em=DoctrineEntityManagerFactory::create();$repo=new DoctrineSubjectRepository($em);$create=new CreateSubjectService($repo,new SubjectResponseMapper(),new DoctrineTransactionManager($em));$list=new ListSubjectsService($repo,new SubjectResponseMapper());$identity=new IdentityRequestFactory();$app->get('/v1/syllabi/{syllabusId}/subjects',function(ServerRequestInterface $r,ResponseInterface $p,array $a)use($identity,$list):ResponseInterface{$u=$this->user($r,$p,$identity);return $u instanceof ResponseInterface?$u:$this->responses->success($p,$list->list((string)$a['syllabusId']),(string)$r->getAttribute('request_id'));});$app->post('/v1/subjects',function(ServerRequestInterface $r,ResponseInterface $p)use($identity,$create):ResponseInterface{$u=$this->admin($r,$p,$identity);if($u instanceof ResponseInterface)return $u;try{$d=json_decode((string)$r->getBody(),true,512,JSON_THROW_ON_ERROR);if(!is_array($d)||!is_string($d['syllabus_id']??null)||!is_string($d['name']??null))throw new InvalidArgumentException();$out=$create->create(new CreateSubjectRequestDto($d['syllabus_id'],$d['parent_id']??null,$d['name'],is_int($d['sort_order']??null)?$d['sort_order']:0));return $this->responses->success($p,$out,(string)$r->getAttribute('request_id'),201);}catch(InvalidArgumentException|DomainException){return $this->responses->problem($p,'VALIDATION_FAILED','Um ou mais campos sao invalidos.',422,(string)$r->getAttribute('request_id'));}});}
private function user(ServerRequestInterface $r,ResponseInterface $p,IdentityRequestFactory $i):CurrentUserResponseDto|ResponseInterface{try{return $this->auth->currentUser($i->accessToken($r));}catch(DomainException|UnavailableUserException|InvalidArgumentException){return $this->responses->problem($p,'UNAUTHENTICATED','Credenciais invalidas ou expiradas.',401,(string)$r->getAttribute('request_id'));}}
private function admin(ServerRequestInterface $r,ResponseInterface $p,IdentityRequestFactory $i):CurrentUserResponseDto|ResponseInterface{$u=$this->user($r,$p,$i);return $u instanceof ResponseInterface||in_array('ADMIN',$u->roles,true)?$u:$this->responses->problem($p,'FORBIDDEN','Permissao insuficiente.',403,(string)$r->getAttribute('request_id'));}}
